def entry_for(scope,cik,document_hash):
    from .sec_html_reviewed import plan_for
    entry=deepcopy(REGISTERED.get(scope))
    if not entry:raise ValueError('Unknown reviewed addition scope')
    if entry.get('mode') not in (None,'native_statement_scope_correction'):
        raise ValueError('Unknown reviewed addition mode')
    plan=entry['plan'];base=plan_for(document_hash,cik)
    if (not base or base['plan_hash']!=entry['parent_plan_hash']
            or plan['cik']!=str(int(cik)).zfill(10) or plan['document_hash']!=document_hash
            or plan.get('source_mode')!=base.get('source_mode')):
        raise ValueError('Reviewed addition parent/source differs')
    body=deepcopy(entry);body['plan'].pop('plan_hash');body['plan'].pop('review_scope_id')
    if digest(body)!=scope:raise ValueError('Reviewed addition seal differs')
    old={digest(f['locator']):f for f in base['facts']}
    new=[digest(f['locator']) for f in plan['facts']]
    correction=entry.get('mode')=='native_statement_scope_correction'
    if len(set(new))!=len(new) or (not correction and set(old).intersection(new)):
        raise ValueError('Reviewed addition repeats a selected source cell')
    if correction:
        if plan.get('native_scope_policy')!='nearest_statement_heading_v1':
            raise ValueError('Native scope correction lacks table ownership policy')
        for fact in plan['facts']:
            prior=old.get(digest(fact['locator']))
            if prior is None:continue
            changed={'concept','native','table_proof','evidence'}
            if (not prior.get('native') or not fact.get('native') or prior['concept']==fact['concept']
                    or {k:v for k,v in prior.items() if k not in changed}
                    !={k:v for k,v in fact.items() if k not in changed}):
                raise ValueError('Native scope correction changes a reported value or context')
        if entry.get('replaces_fact_keys')!=replacement_keys(base,plan):
            raise ValueError('Native scope correction retirement keys differ')
    return entry


def replacement_keys(base,plan):
    """Retire only groups whose every old locator had the wrong native scope.

    A group also supported by the actual primary statement stays admitted.
    Numeric values, periods, units and original receipts are never rewritten.
    """
    from pipelines.fundamentals.additive import identities
    new={digest(f['locator']):f for f in plan['facts']}
    changed=set();groups={}
    for position,fact in enumerate(base['facts']):
        row=identities([dict(fact,value=fact['expected_value'],dimensions=fact.get('dimensions',()))])[0]
        groups.setdefault((row['metric'],row['context_id']),set()).add(position)
        other=new.get(digest(fact['locator']))
        if other and fact['concept']!=other['concept']:changed.add(position)
    return [list(key) for key,positions in sorted(groups.items()) if positions<=changed]
